//! dump_spell_components — Wave 14 / Phase 44 regenerator.
//!
//! Opens `client_portal.dat`, parses the SpellComponentsTable
//! (DID `0x0E00000F`), and emits JSON to stdout matching the
//! schema consumed by
//! `apps/holtburger-web/data/spell-components.json` (and downstream
//! by `scripts/gen-spell-cast-sequence.cjs`).
//!
//! Usage:
//!   cargo run -p holtburger-dat --example dump_spell_components \
//!     > apps/holtburger-web/data/spell-components.json
//!
//! Looks up the DAT path via `HOLTBURGER_PORTAL_DAT` or the
//! workspace-relative fallbacks in `holtburger_dat::utils::get_portal_dat_path`
//! (final fallback `$HOME/ac_base_dats/client_portal.dat`).
//! Exit 2 if the DAT can't be located or parsed.
//!
//! Schema (key = component id as decimal string, sorted numerically):
//!
//! ```json
//! {
//!   "_comment": "Generated by `cargo run -p holtburger-dat --example dump_spell_components`.",
//!   "_source_file_id": "0x0E00000F",
//!   "_component_count": 163,
//!   "components": {
//!     "1": {
//!       "name": "Lead Scarab",
//!       "category": 0,
//!       "iconDid": "0x060013E7",
//!       "type": 1,
//!       "typeName": "Scarab",
//!       "gesture": "0x80000000",
//!       "gestureName": "Invalid",
//!       "time": 0.0,
//!       "text": "",
//!       "cdm": 0.1
//!     },
//!     "2": {
//!       "name": "Iron Scarab",
//!       "type": 1,
//!       "typeName": "Scarab",
//!       "gesture": "0x10000070",
//!       "gestureName": "MagicPowerUp02",
//!       "time": 0.0,
//!       "cdm": 0.1,
//!       ...
//!     }
//!   }
//! }
//! ```
//!
//! Both raw u32 values (as hex strings to preserve sign-bit fidelity)
//! AND symbolic names are emitted so the JS consumer can render
//! either form without re-parsing.

use binrw::BinRead;
use binrw::io::Cursor;
use holtburger_dat::DatDatabase;
use holtburger_dat::file_type::{SpellComponent, SpellComponentsTable};
use std::path::PathBuf;
use std::process::ExitCode;

fn resolve_dat_path() -> Option<PathBuf> {
    if let Some(path) = holtburger_dat::utils::get_portal_dat_path() {
        return Some(path);
    }
    if let Ok(home) = std::env::var("HOME") {
        let p = PathBuf::from(home).join("ac_base_dats/client_portal.dat");
        if p.exists() {
            return Some(p);
        }
    }
    None
}

/// `SpellComponentsTable.Type` enum
/// (`ACE.DatLoader/FileTypes/SpellComponentsTable.cs:10-21`).
fn type_name(t: u32) -> &'static str {
    match t {
        1 => "Scarab",
        2 => "Herb",
        3 => "Powder",
        4 => "Potion",
        5 => "Talisman",
        6 => "Taper",
        7 => "PotionPea",
        _ => "Unknown",
    }
}

/// MotionCommand name lookup for the gestures actually used by the
/// magic-cast pipeline. The full 409-entry table lives in
/// `apps/holtburger-web/data/motion-command-names.json`; here we just
/// cover the windup + cast ranges so the JSON is human-readable
/// without round-tripping through the JS table.
fn gesture_name(g: u32) -> Option<&'static str> {
    match g {
        0x0 => Some("Invalid"),
        0x8000_0000 => Some("Invalid"),
        // Cast gestures (talisman.Gesture)
        0x4000_002B => Some("MagicBlast"),
        0x4000_002C => Some("MagicSelfHead"),
        0x4000_002D => Some("MagicSelfHeart"),
        0x4000_002E => Some("MagicBonus"),
        0x4000_002F => Some("MagicClap"),
        0x4000_0030 => Some("MagicHarm"),
        0x4000_0031 => Some("MagicHeal"),
        0x4000_0032 => Some("MagicThrowMissile"),
        0x4000_0033 => Some("MagicRecoilMissile"),
        0x4000_0034 => Some("MagicPenalty"),
        0x4000_0035 => Some("MagicTransfer"),
        0x4000_0036 => Some("MagicVision"),
        0x4000_0037 => Some("MagicEnchantItem"),
        0x4000_0038 => Some("MagicPortal"),
        0x4000_0039 => Some("MagicPray"),
        0x4000_00D3 => Some("CastSpell"),
        // Windup gestures (scarab.Gesture)
        0x1000_006F => Some("MagicPowerUp01"),
        0x1000_0070 => Some("MagicPowerUp02"),
        0x1000_0071 => Some("MagicPowerUp03"),
        0x1000_0072 => Some("MagicPowerUp04"),
        0x1000_0073 => Some("MagicPowerUp05"),
        0x1000_0074 => Some("MagicPowerUp06"),
        0x1000_0075 => Some("MagicPowerUp07"),
        0x1000_0076 => Some("MagicPowerUp08"),
        0x1000_0077 => Some("MagicPowerUp09"),
        0x1000_0078 => Some("MagicPowerUp10"),
        // Purple variants
        0x1000_012B => Some("MagicPowerUp01Purple"),
        0x1000_012C => Some("MagicPowerUp02Purple"),
        0x1000_012D => Some("MagicPowerUp03Purple"),
        0x1000_012E => Some("MagicPowerUp04Purple"),
        0x1000_012F => Some("MagicPowerUp05Purple"),
        0x1000_0130 => Some("MagicPowerUp06Purple"),
        0x1000_0131 => Some("MagicPowerUp07Purple"),
        0x1000_0132 => Some("MagicPowerUp08Purple"),
        0x1000_0133 => Some("MagicPowerUp09Purple"),
        0x1000_0134 => Some("MagicPowerUp10Purple"),
        _ => None,
    }
}

fn escape_json_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn float_repr(f: f32) -> String {
    if f.is_nan() {
        "0".to_string()
    } else if f == 0.0 {
        "0".to_string()
    } else if f.fract() == 0.0 {
        format!("{}", f as i64)
    } else {
        // Stable, compact f32 repr.
        let s = format!("{f}");
        s
    }
}

fn emit_component_json(out: &mut String, comp: &SpellComponent) {
    out.push_str("{\"name\":");
    out.push_str(&escape_json_str(&comp.name));
    out.push_str(",\"category\":");
    out.push_str(&comp.category.to_string());
    out.push_str(",\"iconDid\":");
    out.push_str(&escape_json_str(&format!("0x{:08X}", comp.icon_did)));
    out.push_str(",\"type\":");
    out.push_str(&comp.ty.to_string());
    out.push_str(",\"typeName\":");
    out.push_str(&escape_json_str(type_name(comp.ty)));
    out.push_str(",\"gesture\":");
    out.push_str(&escape_json_str(&format!("0x{:08X}", comp.gesture)));
    out.push_str(",\"gestureName\":");
    match gesture_name(comp.gesture) {
        Some(name) => out.push_str(&escape_json_str(name)),
        None => out.push_str("null"),
    }
    out.push_str(",\"time\":");
    out.push_str(&float_repr(comp.time));
    out.push_str(",\"text\":");
    out.push_str(&escape_json_str(&comp.text));
    out.push_str(",\"cdm\":");
    out.push_str(&float_repr(comp.cdm));
    out.push('}');
}

fn main() -> ExitCode {
    let Some(dat_path) = resolve_dat_path() else {
        eprintln!(
            "client_portal.dat not found: set HOLTBURGER_PORTAL_DAT or place a copy at \
             ~/ac_base_dats/client_portal.dat"
        );
        return ExitCode::from(2);
    };

    let dat = match DatDatabase::new(&dat_path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("failed to open {}: {e}", dat_path.display());
            return ExitCode::from(2);
        }
    };

    let bytes = match dat.get_file(SpellComponentsTable::FILE_ID) {
        Ok(b) => b,
        Err(e) => {
            eprintln!(
                "SpellComponentsTable 0x{:08X} not in DAT: {e}",
                SpellComponentsTable::FILE_ID
            );
            return ExitCode::from(2);
        }
    };

    let mut cursor = Cursor::new(&bytes);
    let table = match SpellComponentsTable::read_le(&mut cursor) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("SpellComponentsTable parse failed: {e}");
            return ExitCode::from(2);
        }
    };

    // Sort by numeric component id for diff stability + JS consumer
    // sanity (we expect 1..198 sparse).
    let mut entries: Vec<(u32, &SpellComponent)> =
        table.components.iter().map(|(k, v)| (*k, v)).collect();
    entries.sort_by_key(|(id, _)| *id);

    let mut out = String::with_capacity(20_000);
    out.push_str("{\n");
    out.push_str("  \"_comment\": \"Generated by `cargo run -p holtburger-dat --example dump_spell_components`. Source: client_portal.dat file 0x0E00000F (SpellComponentsTable). Schema: ACE.DatLoader/Entity/SpellComponentBase.cs + DRW dats.xml:3003-3014. Both raw u32 (hex string) and symbolic name emitted for type + gesture so the JS consumer can render either. Lead Scarab gesture is MotionCommand.Invalid (0x80000000) — this is the retail encoding behind SpellFormula.cs:265 HasWindupGestures Lead exemption.\",\n");
    out.push_str(&format!(
        "  \"_source_file_id\": \"0x{:08X}\",\n",
        SpellComponentsTable::FILE_ID
    ));
    out.push_str(&format!(
        "  \"_component_count\": {},\n",
        entries.len()
    ));
    out.push_str("  \"components\": {\n");
    let last_idx = entries.len().saturating_sub(1);
    for (i, (id, comp)) in entries.iter().enumerate() {
        out.push_str(&format!("    \"{}\": ", id));
        emit_component_json(&mut out, comp);
        if i < last_idx {
            out.push(',');
        }
        out.push('\n');
    }
    out.push_str("  }\n");
    out.push_str("}\n");

    print!("{out}");

    ExitCode::SUCCESS
}
